"""Repeatable waypoint benchmarks and a preview generated by the actual simulator."""

from __future__ import annotations

import json
import os
import time
from pathlib import Path

import numpy as np

from .session import FlightSession, Mode


def benchmark(config, mode=Mode.BASELINE, learned=None, trials=5, seed=91):
    if trials < 1:
        raise ValueError("trials must be positive")
    rng = np.random.default_rng(seed)
    flights = []
    for i in range(trials):
        session = FlightSession(config, mode, learned)
        w = config.world
        goal = [rng.uniform(0.15, 0.85) * w.width, rng.uniform(0.2, 0.8) * w.height]
        session.set_goal(goal)
        session.toggle_pause()
        milliseconds = []
        while session.status == "running":
            start = time.perf_counter()
            session.tick()
            milliseconds.append((time.perf_counter() - start) * 1000)
        flights.append(
            {
                "trial": i,
                "goal": goal,
                "status": session.status,
                "final_distance_m": float(np.linalg.norm(session.plant.state[:2] - goal)),
                "simulation_seconds": session.plant.time,
                "mean_step_ms": float(np.mean(milliseconds)),
                "p95_step_ms": float(np.percentile(milliseconds, 95)),
            }
        )
        print(
            f"Flight {i + 1}/{trials}: {session.status}, "
            f"error {flights[-1]['final_distance_m']:.3f} m",
            flush=True,
        )
    return {
        "mode": mode.value,
        "seed": seed,
        "config": config.to_dict(),
        "flights": flights,
        "arrival_rate": sum(f["status"] == "arrived" for f in flights) / trials,
        "note": "No human input; goals sampled before each episode.",
    }


def export_preview(output, config, learned=None):
    output = Path(output)
    output.parent.mkdir(parents=True, exist_ok=True)
    os.environ.setdefault("PYGAME_HIDE_SUPPORT_PROMPT", "1")
    import pygame
    from PIL import Image

    from .view import Renderer

    had_font = pygame.font.get_init()
    renderer = Renderer(config)
    surface = pygame.Surface(renderer.size)
    frames = []
    modes = [Mode.MANUAL, Mode.BASELINE] + ([Mode.LEARNED] if learned is not None else [])
    for mode in modes:
        session = FlightSession(config, mode, learned)
        session.set_goal([14, 6])
        session.toggle_pause()
        duration = 5 if mode is Mode.MANUAL else 10
        for step in range(round(duration / config.world.control_dt)):
            if mode is Mode.MANUAL:
                steer = 0.45 if step * config.world.control_dt < 1.3 else -0.3 if step < 60 else 0
                lift = 0.14 if step < 55 else -0.04
                session.tick(steer=steer, lift=lift)
            else:
                session.tick()
            if step % 2 == 0:
                toast = "Preview: scripted manual key replay" if mode is Mode.MANUAL else ""
                renderer.draw(surface, session, toast)
                frame = Image.frombytes("RGB", renderer.size, pygame.image.tobytes(surface, "RGB"))
                frames.append(frame.resize((880, 592), Image.Resampling.LANCZOS))
                if mode is Mode.BASELINE and step == 80:
                    frame.save(Path(output).with_suffix(".png"))
    frames[0].save(
        output,
        save_all=True,
        append_images=frames[1:],
        duration=round(2000 * config.world.control_dt),
        loop=0,
        optimize=True,
    )
    if not had_font:
        pygame.font.quit()
    return {"gif": str(output), "frames": len(frames), "modes": [m.value for m in modes]}


def write_report(report, path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(report, indent=2) + "\n", encoding="utf-8")
